package com.makemytrip.makemytrip.services;

import com.makemytrip.makemytrip.models.*;
import com.makemytrip.makemytrip.repositories.*;
import org.junit.jupiter.api.Test;
import org.springframework.test.util.ReflectionTestUtils;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

class FlightStatusAndRecommendationTest {
 @Test void mockStatusUsesExistingFlightAndStoresStatus(){FlightRepository flights=mock(FlightRepository.class);FlightStatusRepository statuses=mock(FlightStatusRepository.class);Flight f=new Flight();f.setId("f1");f.setFlightName("AB123");f.setFrom("DEL");f.setTo("BOM");f.setDepartureTime("2026-11-01T09:00");f.setArrivalTime("2026-11-01T11:00");when(flights.findById("f1")).thenReturn(Optional.of(f));when(statuses.findByFlightId("f1")).thenReturn(Optional.empty());when(statuses.save(any())).thenAnswer(i->i.getArgument(0));FlightStatus status=new FlightStatusService(flights,statuses).get("f1");assertEquals("AB123",status.getFlightNumber());assertEquals(FlightStatus.State.ON_TIME,status.getStatus());verify(statuses).save(any());}
 @Test void statusUpdateUsesMockServiceAndStatusEnum(){FlightRepository flights=mock(FlightRepository.class);FlightStatusRepository statuses=mock(FlightStatusRepository.class);Flight f=new Flight();f.setId("f1");f.setFlightName("AB123");when(flights.findById("f1")).thenReturn(Optional.of(f));when(statuses.findByFlightId("f1")).thenReturn(Optional.empty());when(statuses.save(any())).thenAnswer(i->i.getArgument(0));FlightStatus input=new FlightStatus();input.setStatus(FlightStatus.State.DELAYED);input.setDelayMinutes(45);input.setDelayReason("WEATHER");FlightStatus actual=new FlightStatusService(flights,statuses).update("f1",input);assertEquals(FlightStatus.State.DELAYED,actual.getStatus());assertEquals(45,actual.getDelayMinutes());assertFalse(actual.isSimulated());}
 @Test void mockSimulationAdvancesDeterministicallyAfterConfiguredInterval(){FlightRepository flights=mock(FlightRepository.class);FlightStatusRepository statuses=mock(FlightStatusRepository.class);Flight f=new Flight();f.setId("f1");when(flights.findById("f1")).thenReturn(Optional.of(f));FlightStatus existing=new FlightStatus();existing.setFlightId("f1");existing.setStatus(FlightStatus.State.ON_TIME);existing.setSimulated(true);existing.setLastUpdated(Instant.now().minusSeconds(120));when(statuses.findByFlightId("f1")).thenReturn(Optional.of(existing));when(statuses.save(any())).thenAnswer(i->i.getArgument(0));FlightStatusService service=new FlightStatusService(flights,statuses);ReflectionTestUtils.setField(service,"simulationEnabled",true);ReflectionTestUtils.setField(service,"simulationIntervalSeconds",60L);assertEquals(FlightStatus.State.BOARDING,service.get("f1").getStatus());verify(statuses).save(existing);}
 @Test void deterministicMockCanRepresentADelay(){FlightRepository flights=mock(FlightRepository.class);FlightStatusRepository statuses=mock(FlightStatusRepository.class);Flight f=new Flight();f.setId("f3");when(flights.findById("f3")).thenReturn(Optional.of(f));FlightStatus existing=new FlightStatus();existing.setFlightId("f3");existing.setFlightNumber("AB123");existing.setStatus(FlightStatus.State.BOARDING);existing.setSimulated(true);existing.setLastUpdated(Instant.now().minusSeconds(120));existing.setEstimatedDeparture("2026-11-01T09:00");existing.setEstimatedArrival("2026-11-01T11:00");when(statuses.findByFlightId("f3")).thenReturn(Optional.of(existing));when(statuses.save(any())).thenAnswer(i->i.getArgument(0));FlightStatusService service=new FlightStatusService(flights,statuses);ReflectionTestUtils.setField(service,"simulationEnabled",true);ReflectionTestUtils.setField(service,"simulationIntervalSeconds",60L);FlightStatus delayed=service.get("f3");assertEquals(FlightStatus.State.DELAYED,delayed.getStatus());assertEquals(15,delayed.getDelayMinutes());assertEquals("2026-11-01T09:15",delayed.getEstimatedDeparture());}
 @Test void mockStatusChangesAreForwardedToFlightNotificationService(){FlightRepository flights=mock(FlightRepository.class);FlightStatusRepository statuses=mock(FlightStatusRepository.class);FlightNotificationService notifications=mock(FlightNotificationService.class);Flight f=new Flight();f.setId("f1");when(flights.findById("f1")).thenReturn(Optional.of(f));FlightStatus before=new FlightStatus();before.setFlightId("f1");before.setStatus(FlightStatus.State.ON_TIME);when(statuses.findByFlightId("f1")).thenReturn(Optional.of(before));when(statuses.save(any())).thenAnswer(i->i.getArgument(0));FlightStatus input=new FlightStatus();input.setStatus(FlightStatus.State.BOARDING);new FlightStatusService(flights,statuses,notifications).update("f1",input);verify(notifications).statusChanged(argThat(s->s.getStatus()==FlightStatus.State.ON_TIME),argThat(s->s.getStatus()==FlightStatus.State.BOARDING));}
 @Test void recommendationsUseHistoryAndIncludeReasonAndScore(){Booking history=new Booking();history.setUserId("u1");history.setBookingType(Booking.Type.FLIGHT);history.setFlightId("old");Flight old=new Flight();old.setId("old");old.setTo("BALI");Flight candidate=new Flight();candidate.setId("new");candidate.setFlightNumber("XY1");candidate.setTo("BALI");Hotel hotel=new Hotel();hotel.setId("h1");hotel.sethotelName("Stay");hotel.setLocation("BALI");BookingRepository bookings=mock(BookingRepository.class);FlightRepository flights=mock(FlightRepository.class);HotelRepository hotels=mock(HotelRepository.class);RecommendationRepository recommendations=mock(RecommendationRepository.class);when(bookings.findByUserId("u1")).thenReturn(List.of(history));when(flights.findById("old")).thenReturn(Optional.of(old));when(flights.findAll()).thenReturn(List.of(old,candidate));when(hotels.findAll()).thenReturn(List.of(hotel));when(recommendations.findByUserIdAndTargetIdAndRecommendationType(anyString(),anyString(),any())).thenReturn(Optional.empty());when(recommendations.save(any())).thenAnswer(i->i.getArgument(0));List<Recommendation> result=new RecommendationService(bookings,flights,hotels,recommendations).forUser("u1");assertEquals(2,result.size());assertTrue(result.stream().allMatch(r->r.getScore()==1&&!r.getReason().isBlank()));}
 @Test void feedbackChangesScoreAndCannotTargetAnotherUsersRecommendation(){BookingRepository bookings=mock(BookingRepository.class);RecommendationRepository repo=mock(RecommendationRepository.class);Recommendation item=new Recommendation();item.setUserId("u1");item.setScore(2);when(repo.findByIdAndUserId("r1","u1")).thenReturn(Optional.of(item));when(repo.findByIdAndUserId("r1","u2")).thenReturn(Optional.empty());when(repo.save(any())).thenAnswer(i->i.getArgument(0));RecommendationService service=new RecommendationService(bookings,mock(FlightRepository.class),mock(HotelRepository.class),repo);assertEquals(4,service.feedback("r1","u1",Recommendation.Feedback.HELPFUL).getScore());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.feedback("r1","u2",Recommendation.Feedback.HELPFUL));}
 @Test void noHistoryReturnsNoPersonalizedRecommendations(){BookingRepository bookings=mock(BookingRepository.class);when(bookings.findByUserId("u1")).thenReturn(List.of());RecommendationService s=new RecommendationService(bookings,mock(FlightRepository.class),mock(HotelRepository.class),mock(RecommendationRepository.class));assertTrue(s.forUser("u1").isEmpty());}
}
